"""FastAPI application: REST API + web investigation interface (``amlgm serve``; ``api`` extra).

* ``/health``, ``/score``, ``/explain``, ``/scan`` — stateless scoring of posted transactions;
* ``/api/...`` — investigations: datasets loaded in memory, alerts, transactions, accounts,
  explanations and exports (back end of the web interface);
* ``/ui/`` — the web investigation interface (static single-page application);
* ``/docs`` and ``/openapi.json`` — the OpenAPI 3.1 documentation generated by FastAPI.

With ``api_key`` (``amlgm serve`` reads ``$AMLGM_API_KEY``) the scoring and investigation routes
require that key in the ``X-API-Key`` header; ``/health``, the documentation and the static files
of the web interface stay open (the interface asks for the key on the first refusal).
"""

import hmac
from pathlib import Path
from typing import Annotated, Any

from ..utils import has_module, require

require("fastapi", "api", "the REST API")

from fastapi import APIRouter, FastAPI, File, Form, Query, Request, UploadFile  # noqa: E402
from fastapi.responses import (  # noqa: E402
    JSONResponse,
    PlainTextResponse,
    RedirectResponse,
)
from fastapi.staticfiles import StaticFiles  # noqa: E402
from pydantic import BaseModel, Field  # noqa: E402

from .. import __version__  # noqa: E402
from ..exceptions import AMLGraphMinerError, ConfigError, NotFoundError  # noqa: E402
from .investigation import InvestigationService  # noqa: E402
from .schemas import (  # noqa: E402
    ExplainRequest,
    HealthResponse,
    ScanRequest,
    ScoreRequest,
    ScoreResponse,
)
from .service import ScoringService, error_payload  # noqa: E402

STATIC_DIR = Path(__file__).with_name("static")
MAX_UPLOAD_MB = 512
API_KEY_HEADER = "X-API-Key"
# routes that read or analyse transactions (everything else is documentation or static files)
PROTECTED_ROUTES = ("/score", "/explain", "/scan")
PROTECTED_PREFIX = "/api/"


class DemoRequest(BaseModel):
    """Size of the synthetic demo dataset."""

    accounts: int = Field(default=1500, ge=50, le=200_000)
    background: int = Field(default=15_000, ge=100, le=2_000_000)
    illicit_ratio: float = Field(default=0.02, gt=0, lt=0.5)
    seed: int = 0


def create_app(
    model: str | Path | ScoringService,
    *,
    datasets: list[str | Path] | None = None,
    demo: bool = False,
    max_upload_mb: int = MAX_UPLOAD_MB,
    api_key: str | None = None,
) -> FastAPI:
    """Build the app around a saved detector directory (or a ready :class:`ScoringService`).

    Parameters
    ----------
    datasets:
        Files analysed at start-up and shown in the web interface.
    demo:
        Also analyse a synthetic demo dataset at start-up.
    max_upload_mb:
        Largest file accepted by the upload endpoint.
    api_key:
        When set, the scoring and investigation routes answer 401 unless the request carries
        this key in the ``X-API-Key`` header (compared in constant time).
    """
    service = model if isinstance(model, ScoringService) else ScoringService.from_dir(model)
    investigations = InvestigationService(service.detector)
    for path in datasets or []:
        investigations.add_file(path)
    if demo:
        investigations.add_demo()

    app = FastAPI(
        title="AML-GraphMiner API",
        version=__version__,
        description=(
            "Score, scan and explain financial transactions with a trained AML detector. "
            "The web investigation interface is served at `/ui/`."
        ),
    )
    app.state.service = service
    app.state.investigations = investigations

    if api_key:
        expected = api_key.encode()

        @app.middleware("http")
        async def _require_api_key(request: Request, call_next: Any) -> Any:
            path = request.scope.get("path", "")
            if path.startswith(PROTECTED_PREFIX) or path.rstrip("/") in PROTECTED_ROUTES:
                given = request.headers.get(API_KEY_HEADER, "").encode()
                if not hmac.compare_digest(given, expected):
                    return JSONResponse(
                        status_code=401,
                        content={
                            "error": "unauthorized",
                            "detail": f"missing or invalid API key (header {API_KEY_HEADER})",
                        },
                    )
            return await call_next(request)

    @app.exception_handler(NotFoundError)
    async def _not_found(_: Request, exc: NotFoundError) -> JSONResponse:
        return JSONResponse(status_code=404, content={"error": "not_found", "detail": str(exc)})

    @app.exception_handler(AMLGraphMinerError)
    async def _library_error(_: Request, exc: AMLGraphMinerError) -> JSONResponse:
        return JSONResponse(status_code=422, content=error_payload(exc))

    # ------------------------------------------------------------------ stateless scoring
    @app.get("/health", response_model=HealthResponse, tags=["scoring"])
    def health() -> dict[str, Any]:
        return service.health()

    @app.post("/score", response_model=ScoreResponse, tags=["scoring"])
    def score(request: ScoreRequest) -> dict[str, Any]:
        return service.score(request.transactions, request.context, request.threshold)

    @app.post("/explain", tags=["scoring"])
    def explain(request: ExplainRequest) -> dict[str, Any]:
        return service.explain(
            request.transactions, request.row, request.method, request.hops, request.max_edges
        )

    @app.post("/scan", tags=["scoring"])
    def scan(request: ScanRequest) -> dict[str, Any]:
        return service.scan(request.transactions, request.top)

    # ------------------------------------------------------------------ investigations
    api = APIRouter(prefix="/api", tags=["investigation"])

    @api.get("/model")
    def model_info() -> dict[str, Any]:
        """Loaded detector, decision threshold and available explanation methods."""
        return investigations.model()

    @api.get("/datasets")
    def list_datasets() -> list[dict[str, Any]]:
        return investigations.datasets()

    @api.post("/datasets/demo")
    def demo_dataset(request: DemoRequest) -> dict[str, Any]:
        """Generate and analyse a synthetic IBM-AML-like dataset."""
        return investigations.add_demo(
            accounts=request.accounts,
            background=request.background,
            illicit_ratio=request.illicit_ratio,
            seed=request.seed,
        )

    if has_module("python_multipart") or has_module("multipart"):

        @api.post("/datasets/upload")
        async def upload_dataset(
            file: Annotated[UploadFile, File(description="CSV, JSON, JSON-lines or Parquet")],
            layout: Annotated[
                str, Form(alias="schema", description="auto, ibm or canonical")
            ] = "auto",
        ) -> dict[str, Any]:
            """Upload a transaction file (IBM AML or canonical columns) and analyse it."""
            content = await file.read()
            if len(content) > max_upload_mb * 1024 * 1024:
                raise ConfigError(f"file larger than {max_upload_mb} MB")
            return investigations.add_upload(content, file.filename or "upload.csv", schema=layout)

    @api.get("/datasets/{dataset_id}")
    def overview(dataset_id: str) -> dict[str, Any]:
        """Dashboard of a dataset: statistics, alerts per motif, score distribution, metrics."""
        return investigations.overview(dataset_id)

    @api.delete("/datasets/{dataset_id}")
    def delete_dataset(dataset_id: str) -> dict[str, str]:
        investigations.remove(dataset_id)
        return {"status": "deleted", "id": dataset_id}

    @api.get("/datasets/{dataset_id}/alerts")
    def alerts(
        dataset_id: str,
        pattern: str | None = None,
        min_score: float = Query(0.0, ge=0.0, le=1.0),
        limit: int = Query(50, ge=1, le=500),
        offset: int = Query(0, ge=0),
    ) -> dict[str, Any]:
        return investigations.alerts(
            dataset_id, pattern=pattern, min_score=min_score, limit=limit, offset=offset
        )

    @api.get("/datasets/{dataset_id}/alerts/{alert_id}")
    def alert(dataset_id: str, alert_id: int) -> dict[str, Any]:
        return investigations.alert(dataset_id, alert_id)

    @api.get("/datasets/{dataset_id}/transactions")
    def transactions(
        dataset_id: str,
        sort: str = Query("score", pattern="^(score|amount|timestamp)$"),
        descending: bool = True,
        account: str | None = None,
        only_alerts: bool = False,
        pattern: str | None = None,
        limit: int = Query(50, ge=1, le=500),
        offset: int = Query(0, ge=0),
    ) -> dict[str, Any]:
        return investigations.transactions(
            dataset_id,
            sort=sort,
            descending=descending,
            account=account,
            only_alerts=only_alerts,
            pattern=pattern,
            limit=limit,
            offset=offset,
        )

    @api.get("/datasets/{dataset_id}/transactions/{tx_id}")
    def transaction(dataset_id: str, tx_id: int) -> dict[str, Any]:
        return investigations.transaction(dataset_id, tx_id)

    @api.get("/datasets/{dataset_id}/transactions/{tx_id}/explain")
    def explain_transaction(
        dataset_id: str,
        tx_id: int,
        method: str = "auto",
        hops: int | None = Query(None, ge=1, le=4),
        max_edges: int = Query(60, ge=5, le=300),
    ) -> dict[str, Any]:
        return investigations.explain(
            dataset_id, tx_id, method=method, hops=hops, max_edges=max_edges
        )

    @api.get("/datasets/{dataset_id}/accounts/{account}")
    def account(dataset_id: str, account: str) -> dict[str, Any]:
        return investigations.account(dataset_id, account)

    @api.get("/datasets/{dataset_id}/export/alerts.csv", response_class=PlainTextResponse)
    def export_alerts(dataset_id: str) -> PlainTextResponse:
        return _csv(investigations.export_alerts_csv(dataset_id), f"alerts-{dataset_id}.csv")

    @api.get("/datasets/{dataset_id}/export/scores.csv", response_class=PlainTextResponse)
    def export_scores(dataset_id: str) -> PlainTextResponse:
        return _csv(investigations.export_scores_csv(dataset_id), f"scores-{dataset_id}.csv")

    app.include_router(api)

    # ------------------------------------------------------------------ web interface
    @app.get("/", include_in_schema=False)
    def root() -> RedirectResponse:
        return RedirectResponse(url="/ui/")

    app.mount("/ui", StaticFiles(directory=STATIC_DIR, html=True), name="ui")
    return app


def _csv(text: str, filename: str) -> PlainTextResponse:
    return PlainTextResponse(
        text,
        media_type="text/csv",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


__all__ = ["API_KEY_HEADER", "STATIC_DIR", "DemoRequest", "create_app"]
